// HasCiRelations applies the HasEdge predicate on the "ci_relations" edge.
func HasCiRelations() predicate.RelationType {
	return predicate.RelationType(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, CiRelationsTable, CiRelationsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCiRelationsWith applies the HasEdge predicate on the "ci_relations" edge with a given conditions (other predicates).
func HasCiRelationsWith(preds ...predicate.CiRelation) predicate.RelationType {
	return predicate.RelationType(func(s *sql.Selector) {
		step := newCiRelationsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasCiTypeRelations applies the HasEdge predicate on the "ci_type_relations" edge.
func HasCiTypeRelations() predicate.RelationType {
	return predicate.RelationType(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, CiTypeRelationsTable, CiTypeRelationsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCiTypeRelationsWith applies the HasEdge predicate on the "ci_type_relations" edge with a given conditions (other predicates).
func HasCiTypeRelationsWith(preds ...predicate.CiTypeRelation) predicate.RelationType {
	return predicate.RelationType(func(s *sql.Selector) {
		step := newCiTypeRelationsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RelationType) predicate.RelationType {
	return predicate.RelationType(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RelationType) predicate.RelationType {
	return predicate.RelationType(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RelationType) predicate.RelationType {
	return predicate.RelationType(sql.NotPredicates(p))
}
